{"value": {"ask": "async function ask(k,v,md,push){
  if(!v)return;
  $("out").innerHTML='<div class="card"><p class="muted">Reading the file\u2026</p></div>';
  LASTQ={kind:k,v:v,model:md||""};
  let d;
  try{
    const q=new URLSearchParams({kind:k,v:v});
    if(md)q.set("model",md);
    const r=await fetch("/z/api/entity?"+q.toString());
    if(!r.ok){let msg="HTTP "+r.status;
      try{const j=await r.json();if(j&&j.error)msg=j.error}catch(e){}
      throw new Error(msg)}
    d=await r.json();
  }catch(e){
    $("out").innerHTML='<div class="card"><p><strong>The desk did not answer.</strong> '
      +esc(String(e.message||e))+". Nothing is shown rather than something wrong.</p></div>";
    return;
  }
  LAST=d;render(d);
  if(push!==false){
    const u=new URLSearchParams({kind:k,v:v});
    if(md)u.set("model",md);
    history.pushState(null,"","?"+u.toString());
  }
  window.scrollTo({top:0,behavior:"auto"});
}", "loaders": null}}

