{"js":"async()=>{
  const af=await fetch("api/airframe/N373UP").then(r=>r.json());
  const d=document.querySelector('#sd-dossier');
  const frameEl=d.querySelector('[data-sd-frame]');
  const onScreen=d.textContent;
  const cs=(af.cannot_show||[]).filter(s=>onScreen.indexOf(s)===-1);
  const rp=await fetch("api/repeats/N373UP").then(r=>r.json());
  const hrs=[...d.querySelectorAll('.sd-d-hrs')].map(e=>e.textContent);
  const sumHead=[...d.querySelectorAll('h3')].map(h=>h.textContent);
  const csv=document.querySelector('#sd-d-csv');
  const csvHead=await fetch(csv.getAttribute('href')).then(r=>r.text()).then(t=>t.split("\n")[0]);
  return {
    frameMatch: frameEl && frameEl.textContent===af.framing.sentence,
    frameText: frameEl?frameEl.textContent.slice(0,60):null,
    missingCannotShow: cs,
    hoursShown: hrs,
    expectedHours: rp.groups.map(g=>g.hours_between),
    summaryLabels: sumHead,
    csvHref: csv?csv.getAttribute('href'):null,
    csvHead
  };
}","query":"?tail=N373UP"}
